data = ['file.txt', 123, 'image.png', 45.6]

categories = {'text': [], 'number': [], 'image': []}

for item in data:
    if isinstance(item, str) and item.endswith('.png'):
        categories['image'].append(item)
    elif isinstance(item, str):
        categories['text'].append(item)
    else:
        categories['number'].append(item)

print(categories)

